CREATE TABLE activity_connections(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,platform TEXT NOT NULL,generation TEXT NOT NULL,status TEXT NOT NULL,timezone TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 0,payload_json TEXT,last_sync_at TEXT,created_at TEXT NOT NULL,revoked_at TEXT);
CREATE UNIQUE INDEX activity_one_source ON activity_connections(owner_id) WHERE enabled=1;
CREATE TABLE activity_step_days(owner_id TEXT NOT NULL,connection_id TEXT NOT NULL,generation TEXT NOT NULL,activity_date TEXT NOT NULL,timezone TEXT NOT NULL,payload_json TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(owner_id,connection_id,generation,activity_date,timezone));
CREATE TABLE activity_step_goals(owner_id TEXT NOT NULL,version INTEGER NOT NULL,daily_target INTEGER,weekly_target INTEGER,author_id TEXT NOT NULL,author_role TEXT NOT NULL,effective_at TEXT NOT NULL,PRIMARY KEY(owner_id,version));
CREATE TABLE activity_shares(owner_id TEXT NOT NULL,coach_email TEXT NOT NULL,steps INTEGER NOT NULL,cardio INTEGER NOT NULL,heart_rate INTEGER NOT NULL,version INTEGER NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(owner_id,coach_email));
